// WF-2 Lab STUB — Sprint 1 walking skeleton
// Returns a hard-coded reverse-string tool as state.candidate.
// This front-loads the Tool Factory / sandbox wiring before any real LLM prompt.
const state = $input.first().json;
if (!state || state.schema_version !== 1) {
  throw new Error(`WF-2 stub: invalid schema_version ${JSON.stringify(state?.schema_version)}`);
}
// Canned tool: reverses the string it receives via stdin/argv/SANDBOX_INPUT
const code = `
import sys, os
def run(input: str) -> str:
    return input[::-1]
if __name__ == "__main__":
    data = ""
    try:
        if not sys.stdin.isatty():
            data = sys.stdin.read()
    except:
        pass
    if not data and len(sys.argv) > 1:
        data = sys.argv[1]
    if not data:
        data = os.getenv("SANDBOX_INPUT", "")
    # fallback: if still empty, try to find the word after "reverse" in goal
    if not data.strip():
        data = "hello"
    print(run(data.strip()))
`;
state.candidate = {
  tool_name: "reverse_string",
  description: "Reverses the input string (stdin/argv/SANDBOX_INPUT)",
  input_schema: { input: "string" },
  code: code.trim(),
  language: "python"
};
// ensure loop budget exists
state.loop = state.loop || { gate: "test", remaining: 3 };
return [{ json: state }];
